<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require 'includes/media_helpers.php'; require_once 'includes/make_mailer.php'; require 'includes/otp_helpers.php'; require 'includes/toasts.php'; require_admin($pdo);
$messages=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!csrf_check($_POST['csrf']??null)) $messages[]=['kind'=>'danger','text'=>'Session expired. Refresh and try again.'];
    elseif (!verify_account_password($pdo,(int)$_SESSION['user_id'],(string)($_POST['auth_password']??''))) $messages[]=['kind'=>'danger','text'=>'Your current admin password did not match.'];
    else {
        $id=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);
        if (!$id || $id===(int)$_SESSION['user_id']) $messages[]=['kind'=>'danger','text'=>'You cannot change your own employee record here.'];
        elseif (($_POST['action']??'')==='edit_employee') {
            $first=trim((string)($_POST['first_name']??'')); $middle=trim((string)($_POST['middle_name']??'')); $last=trim((string)($_POST['last_name']??'')); $email=strtolower(trim((string)($_POST['email_addr']??''))); $mobile=normalize_mobile(trim((string)($_POST['mobileno']??''))); $address=trim((string)($_POST['home_addr']??'')); $role=(string)($_POST['role']??'');
            if (!preg_match(NAME_RE,$first)||!preg_match(NAME_RE,$last)||($middle!==''&&!preg_match(NAME_RE,$middle))) $messages[]=['kind'=>'danger','text'=>'Enter valid employee names.'];
            if (!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>255||!preg_match(MOBILE_RE,$mobile)||mb_strlen($address)>255||!preg_match('/^[a-z][a-z0-9_]{1,31}$/',$role)||in_array($role,['customer'],true)) $messages[]=['kind'=>'danger','text'=>'Review the employee email, contact number, address, and role.'];
            if (!$messages) { $dup=$pdo->prepare('SELECT 1 FROM user_credentials WHERE email_addr=? AND user_id<>? UNION SELECT 1 FROM user_info WHERE mobileno=? AND user_id<>?'); $dup->execute([$email,$id,$mobile,$id]); if ($dup->fetchColumn()) $messages[]=['kind'=>'danger','text'=>'That email or contact number is already assigned.']; }
            $photoPath=null; if (!$messages && isset($_FILES['photo']) && ($_FILES['photo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE) { try { $photoPath=save_square_employee_photo($_FILES['photo']); } catch (Throwable $e) { $messages[]=['kind'=>'danger','text'=>$e->getMessage()]; } }
            if (!$messages) { $target=$pdo->prepare('SELECT role FROM user_credentials WHERE user_id=?'); $target->execute([$id]); $oldRole=$target->fetchColumn(); if (!$oldRole||$oldRole==='customer') $messages[]=['kind'=>'danger','text'=>'Employee not found.']; elseif ($oldRole==='admin'&&$role!=='admin'&&(int)$pdo->query("SELECT COUNT(*) FROM user_credentials WHERE role='admin' AND is_active=1")->fetchColumn()<=1) $messages[]=['kind'=>'danger','text'=>'The last active admin cannot be changed to another role.']; }
            if (!$messages) { $pdo->beginTransaction(); try { if ($photoPath) $pdo->prepare('UPDATE user_info SET first_name=?,middle_name=?,last_name=?,home_addr=?,mobileno=?,photo_path=? WHERE user_id=?')->execute([$first,$middle?:null,$last,$address?:null,$mobile,$photoPath,$id]); else $pdo->prepare('UPDATE user_info SET first_name=?,middle_name=?,last_name=?,home_addr=?,mobileno=? WHERE user_id=?')->execute([$first,$middle?:null,$last,$address?:null,$mobile,$id]); $pdo->prepare('UPDATE user_credentials SET email_addr=?,role=? WHERE user_id=?')->execute([$email,$role,$id]); $pdo->commit(); $_SESSION['flash_success']='Employee details updated.'; header('Location: employees.php'); exit; } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $messages[]=['kind'=>'danger','text'=>'Could not save employee details.']; } }
        } elseif (($_POST['action']??'')==='toggle_status') {
            $new=(int)($_POST['new_status']??-1); $target=$pdo->prepare("SELECT role,is_active FROM user_credentials WHERE user_id=? AND role<>'customer'"); $target->execute([$id]); $row=$target->fetch();
            if (!$row||!in_array($new,[0,1],true)) $messages[]=['kind'=>'danger','text'=>'Employee status could not be changed.'];
            elseif ((int)$row['is_active']===$new) $messages[]=['kind'=>'info','text'=>'Employee status is already up to date.'];
            elseif ($row['role']==='admin'&&$new===0&&(int)$pdo->query("SELECT COUNT(*) FROM user_credentials WHERE role='admin' AND is_active=1")->fetchColumn()<=1) $messages[]=['kind'=>'danger','text'=>'The last active admin cannot be deactivated.'];
            else { $pdo->prepare('UPDATE user_credentials SET is_active=?,first_login_activation=0 WHERE user_id=?')->execute([$new,$id]); $_SESSION['flash_success']=$new?'Employee account activated.':'Employee account deactivated.'; header('Location: employees.php'); exit; }
        } elseif (($_POST['action']??'')==='reset_staff_password') {
            $target=$pdo->prepare("SELECT c.email_addr,c.role,i.first_name,i.middle_name,i.last_name FROM user_credentials c JOIN user_info i ON i.user_id=c.user_id WHERE c.user_id=?"); $target->execute([$id]); $employee=$target->fetch();
            if (!$employee||$employee['role']!=='staff') $messages[]=['kind'=>'danger','text'=>'Password reset is available for staff accounts only.'];
            else {
                $temporaryPassword='$Nomcha'.random_int(100000,999999); $fullName=trim(implode(' ',array_filter([$employee['first_name'],$employee['middle_name'],$employee['last_name']])));
                try { $pdo->beginTransaction(); $pdo->prepare('UPDATE user_credentials SET password=? WHERE user_id=?')->execute([password_hash($temporaryPassword,PASSWORD_DEFAULT),$id]); $pdo->prepare("UPDATE auth_otp_challenges SET consumed_at=NOW() WHERE user_id=? AND purpose='password_reset' AND consumed_at IS NULL")->execute([$id]); send_employee_welcome_email((string)$employee['email_addr'],$fullName,$temporaryPassword); auth_security_log($pdo,'admin_password_reset',(int)$_SESSION['user_id'],'password_reset','completed',['target_user_id'=>(int)$id]); $pdo->commit(); $_SESSION['flash_success']='Staff password reset. A temporary password was emailed.'; header('Location: employees.php'); exit; }
                catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $messages[]=['kind'=>'danger','text'=>'Password could not be reset or emailed. Check Make setup and try again.']; }
            }
        }
    }
}
$employees=$pdo->prepare("SELECT c.user_id,c.role,c.email_addr,c.is_active,i.first_name,i.middle_name,i.last_name,i.mobileno,i.home_addr,i.photo_path FROM user_credentials c JOIN user_info i ON i.user_id=c.user_id WHERE c.role<>'customer' AND c.user_id<>? ORDER BY i.last_name,i.first_name"); $employees->execute([(int)$_SESSION['user_id']]); $employees=$employees->fetchAll();
$success=$_SESSION['flash_success']??null; unset($_SESSION['flash_success']); if ($success) array_unshift($messages,['kind'=>'success','text'=>$success]);
$pageTitle='Employee management'; require 'includes/header.php'; render_toasts($messages);
?>
<main class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="mb-1">Employee management</h1><p class="text-secondary mb-0">Select an employee to view or update their account.</p></div><a href="employee-create.php" class="btn btn-auth"><i class="bi bi-person-plus me-1"></i>Add employee</a></div>
