<div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3" id="employee-grid">
<?php foreach ($employees as $person): $fullName=trim(implode(' ',array_filter([$person['first_name'],$person['middle_name'],$person['last_name']]))); $personJson=json_encode($person,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP); ?>
<div class="col employee-card-wrap" data-name="<?=e(mb_strtolower($fullName))?>" data-role="<?=e($person['role'])?>"><button type="button" class="employee-grid-card w-100 h-100 text-start p-3" data-employee='<?=e($personJson)?>'><div class="d-flex align-items-center gap-3"><img class="staff-photo" src="<?=e($person['photo_path']?:'assets/employee-placeholder.svg')?>" alt="Photo of <?=e($fullName)?>"><div class="min-w-0"><h2 class="h6 mb-1 text-truncate"><?=e($fullName)?></h2><span class="badge text-bg-secondary"><?=e(ucfirst($person['role']))?></span></div></div><div class="small mt-3 text-secondary text-truncate"><?=e($person['email_addr'])?></div><div class="small text-secondary"><?=e($person['mobileno'])?></div><div class="small mt-2 <?=$person['is_active']?'text-success':'text-danger'?>"><?=$person['is_active']?'Active':'Deactivated'?></div></button></div>
<?php endforeach; ?></div><p id="employee-empty" class="text-secondary mt-3" <?= $employees?'hidden':'' ?>>No employees match your search.</p></main>

