<div class="modal fade" id="editEmployeeModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form id="employeeEditForm" method="post" enctype="multipart/form-data"><div class="modal-header"><h2 class="modal-title fs-5">Edit employee details</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit_employee"><input type="hidden" name="user_id" id="edit-user-id"><div class="row g-3"><div class="col-md-4"><label class="form-label">First name</label><input class="form-control" name="first_name" id="edit-first" required maxlength="100"></div><div class="col-md-4"><label class="form-label">Middle name</label><input class="form-control" name="middle_name" id="edit-middle" maxlength="100"></div><div class="col-md-4"><label class="form-label">Last name</label><input class="form-control" name="last_name" id="edit-last" required maxlength="100"></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" name="email_addr" id="edit-email" type="email" required maxlength="255"></div><div class="col-md-6"><label class="form-label">Contact number</label><input class="form-control" name="mobileno" id="edit-phone" required></div><div class="col-md-8"><label class="form-label">Address</label><input class="form-control" name="home_addr" id="edit-address" maxlength="255"></div><div class="col-md-4"><label class="form-label">Role</label><select class="form-select" name="role" id="edit-role"><?php foreach(array_unique(array_merge(array_column($employees,'role'),['staff','admin'])) as $employeeRole): ?><option value="<?=e($employeeRole)?>"><?=e(ucfirst(str_replace('_',' ',$employeeRole)))?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Replace square photo (optional)</label><input class="form-control" id="employee-photo-input" name="photo" type="file" accept="image/jpeg,image/png,image/webp" data-image-input="#employee-photo-preview"><div class="form-text">A replacement photo must be square (1:1).</div><img id="employee-photo-preview" class="staff-photo mt-2" style="width:92px;height:92px" alt="Photo preview" hidden></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button type="button" class="btn btn-auth" id="openEditConfirm">Save details</button></div></form></div></div></div>

<div class="modal fade" id="editEmployeeConfirm" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5">Confirm employee changes</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><label class="form-label" for="edit-auth-password">Your current admin password</label><input class="form-control" id="edit-auth-password" name="auth_password" form="employeeEditForm" type="password" required autocomplete="current-password"></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-auth" type="submit" form="employeeEditForm">Confirm and save</button></div></div></div></div>

<div class="modal fade" id="employeeStatusConfirm" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h2 class="modal-title fs-5" id="status-title">Confirm status change</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p id="status-copy"></p><label class="form-label">Your current admin password</label><input class="form-control" name="auth_password" type="password" required autocomplete="current-password"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_status"><input type="hidden" name="user_id" id="status-user-id"><input type="hidden" name="new_status" id="status-new-value"></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" id="confirm-status-button">Confirm</button></div></form></div></div></div>
<div class="modal fade" id="resetStaffPasswordConfirm" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h2 class="modal-title fs-5">Reset staff password</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p>A temporary password will be emailed to <strong id="reset-staff-name"></strong>.</p><label class="form-label">Your current admin password</label><input class="form-control mb-3" name="auth_password" type="password" required autocomplete="current-password"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reset_staff_password"><input type="hidden" name="user_id" id="reset-staff-user-id"></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-warning">Confirm and email temporary password</button></div></form></div></div></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{let chosen=null;const details=new bootstrap.Modal('#employeeDetailsModal'),edit=new bootstrap.Modal('#editEmployeeModal'),editConfirm=new bootstrap.Modal('#editEmployeeConfirm'),statusConfirm=new bootstrap.Modal('#employeeStatusConfirm'),resetPasswordConfirm=new bootstrap.Modal('#resetStaffPasswordConfirm');
const cards=[...document.querySelectorAll('[data-employee]')],search=document.getElementById('employee-search'),roleFilter=document.getElementById('role-filter'),sortKey=document.getElementById('sort-key'),sortDir=document.getElementById('sort-dir'),empty=document.getElementById('employee-empty');
function setEdit(){document.getElementById('edit-user-id').value=chosen.user_id;document.getElementById('edit-first').value=chosen.first_name||'';document.getElementById('edit-middle').value=chosen.middle_name||'';document.getElementById('edit-last').value=chosen.last_name||'';document.getElementById('edit-email').value=chosen.email_addr||'';document.getElementById('edit-phone').value=chosen.mobileno||'';document.getElementById('edit-address').value=chosen.home_addr||'';document.getElementById('edit-role').value=chosen.role;const p=document.getElementById('employee-photo-preview');p.src=chosen.photo_path||'assets/employee-placeholder.svg';p.hidden=false;}
cards.forEach(card=>card.addEventListener('click',()=>{chosen=JSON.parse(card.dataset.employee);const name=[chosen.first_name,chosen.middle_name,chosen.last_name].filter(Boolean).join(' ');document.getElementById('detail-photo').src=chosen.photo_path||'assets/employee-placeholder.svg';document.getElementById('detail-name').textContent=name;document.getElementById('detail-role').textContent=chosen.role;document.getElementById('detail-email').textContent=chosen.email_addr||'—';document.getElementById('detail-phone').textContent=chosen.mobileno||'—';document.getElementById('detail-address').textContent=chosen.home_addr||'—';document.getElementById('detail-status').textContent=Number(chosen.is_active)?'Active':'Deactivated';document.getElementById('toggleEmployeeButton').textContent=Number(chosen.is_active)?'Deactivate':'Activate';document.getElementById('toggleEmployeeButton').className='btn '+(Number(chosen.is_active)?'btn-danger':'btn-success');document.getElementById('resetEmployeePasswordButton').hidden=chosen.role!=='staff';details.show();}));
document.getElementById('editEmployeeButton').addEventListener('click',()=>{setEdit();details.hide();edit.show();});document.getElementById('openEditConfirm').addEventListener('click',()=>{const form=document.getElementById('employeeEditForm');if(form.reportValidity()){edit.hide();editConfirm.show();}});
document.getElementById('toggleEmployeeButton').addEventListener('click',()=>{document.getElementById('status-user-id').value=chosen.user_id;document.getElementById('status-new-value').value=Number(chosen.is_active)?0:1;document.getElementById('status-copy').textContent=(Number(chosen.is_active)?'Deactivate':'Activate')+' '+[chosen.first_name,chosen.last_name].filter(Boolean).join(' ')+'?';document.getElementById('confirm-status-button').textContent=Number(chosen.is_active)?'Deactivate employee':'Activate employee';details.hide();statusConfirm.show();});
document.getElementById('resetEmployeePasswordButton').addEventListener('click',()=>{document.getElementById('reset-staff-user-id').value=chosen.user_id;document.getElementById('reset-staff-name').textContent=[chosen.first_name,chosen.middle_name,chosen.last_name].filter(Boolean).join(' ');details.hide();resetPasswordConfirm.show();});
function refresh(){const q=search.value.trim().toLowerCase();const visible=cards.filter(c=>{const show=c.dataset.name.includes(q)&&(!roleFilter.value||c.closest('.employee-card-wrap').dataset.role===roleFilter.value);c.closest('.employee-card-wrap').hidden=!show;return show;});visible.sort((a,b)=>{const av=sortKey.value==='role'?a.dataset.role:a.dataset.name,bv=sortKey.value==='role'?b.dataset.role:b.dataset.name;return av.localeCompare(bv)*(sortDir.value==='asc'?1:-1);});const grid=document.getElementById('employee-grid');visible.forEach(c=>grid.appendChild(c.closest('.employee-card-wrap')));empty.hidden=visible.length>0;}[search,roleFilter,sortKey,sortDir].forEach(control=>control.addEventListener('input',refresh));refresh();
});
</script>
